import { Apple, ArrowDownToLine, ArrowRight, Beef, BookOpen, Carrot, Check, CheckCircle2, ChevronDown, ChevronRight, Clock3, CookingPot, Croissant, Database, Dumbbell, Flame, History, IceCreamBowl, Leaf, Loader2, Minus, Nut, Package, Pencil, Pill, Plus, RefreshCw, Scale, Search, SlidersHorizontal, Soup, Star, Upload, Utensils, Wheat, X } from "lucide-react";
