function ConsumeModal({item,saving,blocked,error,onClose,onSave}:{item:FoodItem;saving:boolean;blocked:boolean;error:string;onClose:()=>void;onSave:(quantity:number,note:string)=>Promise<void>}){const [quantity,setQuantity]=useState(""),[note,setNote]=useState(""),parsed=Number(quantity),valid=quantity!==""&&Number.isFinite(parsed)&&parsed>0&&(item.quantity===null||parsed<=item.quantity);return <Modal title="记录额外用掉的食物" subtitle="已记录实际进食的食物无需重复扣减；这里只记录尚未结算的额外消耗。" onClose={onClose} saving={saving}><form onSubmit={event=>{event.preventDefault();if(valid)void onSave(parsed,note);}}><div className="modal-body consume-modal-body"><div className="consume-food"><span className="food-icon green"><Utensils size={24}/></span><div><strong>{item.name}</strong><p>当前可用余量：{item.quantity===null?"不详":`${num(item.quantity)} ${item.unit}`}</p></div></div><label className="field">菜单以外，额外用掉多少（必填）<div className="input-with-suffix"><input required type="number" min="0.0001" step="any" max={item.quantity??undefined} value={quantity} onChange={event=>setQuantity(event.target.value)} placeholder="输入实际消耗数量"/><span>{item.unit}</span></div></label><label className="field">补充说明（可选）<input value={note} maxLength={500} onChange={event=>setNote(event.target.value)} placeholder="例如：午餐，按实际称重记录"/></label><div className="consume-preview"><span>记录后可用余量</span><strong>{item.quantity===null?"仍保留为余量不详":valid?`${num(item.quantity-parsed)} ${item.unit}`:`${num(item.quantity)} ${item.unit}`}</strong>{item.quantity===null&&<p>已记录消耗，当前余量不会被猜测。</p>}</div>{(blocked||error)&&<p className="form-error" role="alert">{blocked?"库存版本有更新，请关闭弹窗并刷新后重新核对。":error}</p>}</div><div className="modal-footer"><span className="footer-hint"><CheckCircle2 size={14}/>只扣当前这批食物</span><div className="modal-footer-right"><button type="button" className="button secondary" disabled={saving} onClick={onClose}>取消</button><button className="button primary" disabled={!valid||saving||blocked}>{saving?<Loader2 size={16} className="spin"/>:<Check size={16}/>}确认额外消耗</button></div></div></form></Modal>;}
